// AnthropicBackendOptions Anthropic Claude 后端选项。
type AnthropicBackendOptions struct {
	// BaseUrl 自定义API端点URL。留空使用默认值。
	BaseUrl *string `json:"base_url,omitempty"`

	// EnablePromptCache 启用提示缓存（Prompt Caching）。
	// 启用后，system prompt会被标记为ephemeral缓存断点，
	// 可显著降低重复翻译任务的token消耗和延迟。
	EnablePromptCache *bool `json:"enable_prompt_cache,omitempty"`

	// MaxTokens 最大生成 token 数。Anthropic 必填，默认 8192。
	MaxTokens *int `json:"max_tokens,omitempty"`

	// Model 模型名称（必填）。须为 Anthropic 实际可用的模型 ID。
	Model string `json:"model"`

	// ResponseFormat 响应格式：
	// - json_schema: 强制结构化 JSON 输出（推荐）
	// - json_object: 自由 JSON 对象
	// - text: 纯文本
	// - none: 不约束格式
	ResponseFormat *ResponseFormat `json:"response_format,omitempty"`

	// Stream 设为 true 时以流式发起请求并在内部累积为完整响应后返回，
	// 适用于只接受 stream:true 的兼容网关。默认 false。
	Stream *bool `json:"stream,omitempty"`

	// Temperature 采样温度，控制输出的随机性。
	// - 不设置: 使用 API 默认值（通常为 1.0）
	// - 0: 确定性输出
	// - 0.1-0.3: 翻译任务推荐范围
	// - Anthropic范围限制为0-1
	Temperature *float64 `json:"temperature,omitempty"`

	// ThinkingLevel 统一思考强度档位（手动开关式）。不设置该键 = 开关关闭，不传任何 thinking 字段，
	// 沿用模型/网关默认（注意：默认开思考的推理模型在不设置该键时仍会思考，此为 by design）。
	// off = 开关开启且显式关闭思考，映射为各协议原生关闭参数
	// （OpenAI reasoning_effort "none" / Anthropic thinking disabled / Gemini thinkingBudget 0），
	// 该参数的模型兼容性由用户自行保证，LinguaFlow 不做模型能力校验。
	// minimal = 开关开启并选择最低档位，映射为各协议原生最低档参数
	// （OpenAI reasoning_effort "minimal" / Anthropic budget_tokens ≈ max_tokens 的 12.5% / Gemini ThinkingLevel "MINIMAL"）。
	// minimal/low/medium/high = 开关开启并选择档位，由各适配层映射为厂商原生参数。仅对支持推理的模型生效。
	ThinkingLevel *ThinkingLevel `json:"thinking_level,omitempty"`

	// Timeout 请求超时时间（秒）。0 表示不限制。
	Timeout *int `json:"timeout,omitempty"`

	// TopP 核采样参数，控制采样多样性。
	// - 不设置: 使用 API 默认值（通常为 1.0）
	// - 1.0: 不限制
	TopP *float64 `json:"top_p,omitempty"`
	Type string   `json:"type"`
}

